function getFTE(){
    if(typeof sourceContract.weekly_working_hours !== 'undefined' && 
            typeof sourceContract.full_time_weekly_working_hours !== 'undefined' &&
            sourceContract.weekly_working_hours && 
            sourceContract.full_time_weekly_working_hours){
        
        return (sourceContract.weekly_working_hours / sourceContract.full_time_weekly_working_hours);
    }
    else{
        return 0;
    }
}

getFTE();

